mapper.select:
SELECT
    rv.*,
    r.res_name, r.res_code, r.res_type, r.location,
    e.emp_name, d.dept_name, ap.emp_name AS approvedEmpName
FROM reservation rv
JOIN com_resource r ON rv.res_id = r.res_id
JOIN employee e ON rv.emp_id = e.emp_id
JOIN department d ON e.dept_id = d.dept_id
LEFT JOIN employee ap ON rv.approved_emp_id = ap.emp_id
WHERE rv.com_id = #{comId}

    AND r.res_type = #{resType}


    AND ( UPPER(r.res_code) LIKE '%' || #{keyword} || '%'
     OR UPPER(r.res_name) LIKE '%' || #{keyword} || '%' )


    AND rv.emp_id = #{empId}


    AND rv.status = #{status}


    AND rv.updated_at >= #{startDt}


    AND rv.updated_at < #{endDt}

ORDER BY rv.rev_id DESC
OFFSET #{pstartno} ROWS FETCH NEXT #{onepagelist} ROWS ONLY

SELECT COUNT(*)
FROM reservation rv
LEFT JOIN COM_RESOURCE R ON R.RES_ID = RV.RES_ID
WHERE rv.com_id = #{comId}

    AND r.res_type = #{resType}


    AND ( UPPER(r.res_code) LIKE '%' || #{keyword} || '%'
     OR UPPER(r.res_name) LIKE '%' || #{keyword} || '%' )


    AND rv.emp_id = #{empId}


    AND rv.status = #{status}


    AND rv.updated_at >= #{startDt}


    AND rv.updated_at < #{endDt}

mapper.delete:
DELETE FROM reservation
WHERE rev_id = #{revId}
  AND status = 'WAI'

mapper.select:
SELECT NVL(SUM(quantity), 0)
FROM reservation
WHERE res_id = #{resId}
  AND status IN ('WAI','APP','NORET')

    AND rev_id != #{excludeRevId}  

  AND start_dt < #{endDt}
  AND end_dt   > #{startDt}

SELECT COUNT(*)
FROM reservation
WHERE emp_id = #{empId}
  AND rev_id <> #{revId}
  AND noshow_alert_at IS NOT NULL

mapper.update:
UPDATE reservation
   SET noshow_alert_at = SYSTIMESTAMP,
       risk_score      = #{riskScore}
 WHERE rev_id = #{revId}

mapper.delete:
DELETE FROM reservation
WHERE res_id = #{resId}
  AND status = 'REJ'
